/**
 * What is inside a route's first-load JS: decodes each chunk's source map and credits every
 * generated byte to the source file it came from, then groups by package / src directory.
 *
 *   # temporarily set `productionBrowserSourceMaps: true` in next.config.ts, then:
 *   next build && node scripts/dev/perf/bundle-attribution.mjs /find [--top=40] [--depth=2]
 *
 * Sizes are minified (raw) bytes; `gz` is the chunk's gzip ratio applied pro rata, which is
 * close enough to rank by. Only chunks the route's `entryJSFiles` and the framework runtime
 * load on first paint are counted, so lazy chunks do not appear.
 */
import { readFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { gzipSync } from "node:zlib";
import { join } from "node:path";

const route = process.argv[2] ?? "/find";
const MINUS = process.argv.find((a) => a.startsWith("--minus="))?.split("=")[1];
const flag = (n, d) => process.argv.find((a) => a.startsWith(`--${n}=`))?.split("=")[1] ?? d;
const TOP = Number(flag("top", 40));
const NEXT = ".next";

function findManifest(dir, r = route) {
  const want = `${r === "/" ? "" : r}/page_client-reference-manifest.js`;
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) { const hit = findManifest(p, r); if (hit) return hit; }
    else if (p.replace(/\/\([^)]+\)/g, "").endsWith(`/app${want}`)) return p;
  }
}
const root = JSON.parse(readFileSync(join(NEXT, "build-manifest.json"), "utf8")).rootMainFiles ?? [];
function chunkSet(r) {
  const mp = findManifest(join(NEXT, "server", "app"), r);
  if (!mp) throw new Error(`no manifest for ${r}`);
  const g = {};
  new Function("globalThis", readFileSync(mp, "utf8"))(g);
  const [[, manifest]] = Object.entries(g.__RSC_MANIFEST);
  return new Set([...root, ...Object.values(manifest.entryJSFiles ?? {}).flat().map((c) => c.replace(/^\/_next\//, ""))]);
}
const chunks = chunkSet(route);
if (MINUS) for (const c of chunkSet(MINUS)) chunks.delete(c);

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const val = new Map([...B64].map((c, i) => [c, i]));
function decode(mappings) {
  const lines = [];
  let src = 0;
  for (const line of mappings.split(";")) {
    let gc = 0;
    const segs = [];
    for (const seg of line.split(",")) {
      if (!seg) continue;
      const f = [];
      let shift = 0, v = 0;
      for (const ch of seg) {
        const d = val.get(ch);
        v += (d & 31) << shift;
        if (d & 32) shift += 5;
        else { f.push(v & 1 ? -(v >> 1) : v >> 1); v = 0; shift = 0; }
      }
      gc += f[0];
      if (f.length > 1) { src += f[1]; segs.push([gc, src]); }
      else segs.push([gc, -1]);
    }
    lines.push(segs);
  }
  return lines;
}

const key = (s) => {
  const m = s.match(/node_modules\/((?:@[^/]+\/)?[^/]+)/g);
  if (m) {
    const pkg = m[m.length - 1].replace("node_modules/", "");
    const sub = process.env.PKGDEPTH && s.includes(pkg) ? s.slice(s.lastIndexOf(pkg) + pkg.length).split("/").slice(0, Number(process.env.PKGDEPTH) + 1).join("/") : "";
    return "npm:" + pkg + sub;
  }
  const p = s.replace(/^.*?(src\/)/, "$1");
  return p.split("/").slice(0, Number(flag("depth", 3))).join("/");
};

const agg = new Map();
let totalRaw = 0, totalGz = 0;
for (const c of chunks) {
  const f = join(NEXT, c);
  if (!existsSync(f)) continue;
  const code = readFileSync(f, "utf8");
  const gz = gzipSync(code).length;
  totalRaw += code.length; totalGz += gz;
  const ref = code.match(/\/\/# sourceMappingURL=(\S+)\s*$/)?.[1];
  const mapFile = ref ? join(NEXT, "static", "chunks", ref) : f + ".map";
  if (!existsSync(mapFile)) { agg.set("(no map) " + c, (agg.get("(no map) " + c) ?? 0) + code.length); continue; }
  const map = JSON.parse(readFileSync(mapFile, "utf8"));
  const lines = decode(map.mappings);
  const codeLines = code.split("\n");
  const ratio = gz / code.length;
  for (let li = 0; li < lines.length; li++) {
    const segs = lines[li];
    const len = codeLines[li]?.length ?? 0;
    for (let i = 0; i < segs.length; i++) {
      const [col, si] = segs[i];
      const end = i + 1 < segs.length ? segs[i + 1][0] : len;
      const k = si < 0 ? "(unmapped)" : key(map.sources[si] ?? "?");
      agg.set(k, (agg.get(k) ?? 0) + (end - col) * ratio);
    }
  }
}
// agg values are gzip-weighted bytes
const rows = [...agg.entries()].sort((a, b) => b[1] - a[1]);
console.log(`${route}: ${chunks.size} chunks, ${(totalRaw / 1024).toFixed(0)} KB raw, ${(totalGz / 1024).toFixed(0)} KB gz`);
for (const [k, v] of rows.slice(0, TOP)) console.log(`${(v / 1024).toFixed(1).padStart(7)} KB gz  ${k}`);
